function postingPlanRecord(node,index,c){if(node?.type!=="Social Media Posting")return null;const asset=projectAsset(node);if(!asset)return null;const optimistic=optimisticSchedules.get(text(node.id)),schedule=optimistic?optimistic.schedule:readPlanningSchedule(node),eligibility=schedulingEligibility(node,c),finalized=eligibility.finalized,editable=eligibility.editable,destinationLabel=asset.platform.toLowerCase()==="facebook"?text(facebookAction(asset,c).selectedDestination?.label):"";return{...asset,title:safePostTitle(asset,c.language),index,schedule,planningSchedule:schedule,pending:!!optimistic,finalized,editable,locked:finalized||!editable,reason:eligibility.reason,eligibility,hasLink:/https:\/\/\S+/u.test(asset.content),mediaCount:Array.isArray(node.images)?node.images.length:0,destinationLabel};}
