function calendarFilterMatch(r){const f=calendarState.filters,q=calendarState.search.toLowerCase(),hay=[r.title,r.content,r.platform,r.destinationLabel,r.owner,r.funnelStage].join(" ").toLowerCase();return(!q||hay.includes(q))&&(!f.platform||r.platform===f.platform)&&(!f.schedule||f.schedule==="scheduled"&&!!r.schedule||f.schedule==="unscheduled"&&!r.schedule)&&(!f.approval||r.status===f.approval)&&(!f.readiness||r.readiness.level===f.readiness)&&(!f.publication||f.publication==="finalized"&&r.finalized||f.publication==="open"&&!r.finalized)&&(!f.owner||r.owner===f.owner)&&(!f.warning||f.warning==="warning"&&(!!r.reason||r.schedule?.changed));}
