function renderMonth(records,k,t,lang){const [y,m]=k.split("-").map(Number),first=new Date(Date.UTC(y,m-1,1)),start=(first.getUTCDay()-calendarState.firstDay+7)%7,cells=[];for(let i=0;i<42;i++){const dt=new Date(Date.UTC(y,m-1,1-start+i)),key=dt.toISOString().slice(0,10),items=records.filter(r=>r.schedule?.localDate===key),outside=dt.getUTCMonth()!==m-1,today=key===new Date().toISOString().slice(0,10),weekend=[0,6].includes(dt.getUTCDay());cells.push(`<div role="gridcell" tabindex="0" class="content-calendar-day${outside?' is-outside':''}${today?' is-today':''}${weekend?' is-weekend':''}" data-calendar-drop-date="${key}" aria-label="${new Intl.DateTimeFormat(lang,{dateStyle:'full',timeZone:'UTC'}).format(dt)}"><span class="content-calendar-day-number">${dt.getUTCDate()}</span>${items.slice(0,calendarState.density==="compact"?3:2).map(r=>compactCard(r,t)).join("")}${items.length>3?`<button data-calendar-more="${key}">${t.more(items.length-3)}</button>`:""}</div>`);}const weekdays=Array.from({length:7},(_,i)=>new Intl.DateTimeFormat(lang,{weekday:"short",timeZone:"UTC"}).format(new Date(Date.UTC(2024,0,7+calendarState.firstDay+i))));return `<div class="content-calendar-month" role="grid" aria-label="${t.month}"><div class="content-calendar-weekdays" role="row">${weekdays.map(x=>`<span role="columnheader">${x}</span>`).join("")}</div><div class="content-calendar-month-days">${cells.join("")}</div></div>`;}
function renderWeek(records,t,lang){const start=new Date(`${weekAnchor()}T00:00:00Z`),days=Array.from({length:7},(_,i)=>{const d=new Date(start);d.setUTCDate(d.getUTCDate()+i);return d.toISOString().slice(0,10)}),hours=Array.from({length:24},(_,h)=>String(h).padStart(2,"0")+":00");return `<div class="content-calendar-week" role="grid" aria-label="${t.week}"><div class="week-head"><span>${t.time}</span>${days.map(d=>`<strong class="${d===new Date().toISOString().slice(0,10)?'is-today':''}">${new Intl.DateTimeFormat(lang,{weekday:'short',day:'numeric',timeZone:'UTC'}).format(new Date(d+'T00:00:00Z'))}</strong>`).join("")}</div><div class="week-scroll">${hours.map(hour=>`<div class="week-row"><time>${hour}</time>${days.map(date=>`<div tabindex="0" data-calendar-drop-date="${date}" data-calendar-drop-time="${hour}" aria-label="${t.dropTime} ${date} ${hour}">${records.filter(r=>r.schedule?.localDate===date&&r.schedule.localTime.slice(0,2)===hour.slice(0,2)).map(r=>compactCard(r,t)).join("")}</div>`).join("")}</div>`).join("")}</div></div>`;}
function renderList(records,t){const key=r=>calendarState.listGroup==="channel"?(r.platform||"—"):calendarState.listGroup==="schedule"?(r.schedule?t.scheduled:t.unscheduled):(r.schedule?.localDate||t.unscheduled),groups=new Map;records.sort(comparePostingPlan).forEach(r=>{const k=key(r);if(!groups.has(k))groups.set(k,[]);groups.get(k).push(r)});return `<div class="content-calendar-list">${[...groups].map(([label,items])=>`<section><h3>${esc(label)}</h3>${items.map(r=>`<button type="button" class="content-calendar-row" data-calendar-card="${esc(r.id)}"><time>${esc(r.schedule?`${r.schedule.localDate} · ${r.schedule.localTime}`:t.unscheduled)}</time><span><strong>${esc(r.title||r.id)}</strong>${calendarState.showCaption?`<small>${esc(r.content)}</small>`:""}</span><span>${esc(r.platform||"—")}</span>${calendarState.showDestination?`<span>${esc(r.destinationLabel||t.noDestination)}</span>`:""}<span>${esc(statusLabel(r.status,mounted?.context?.language||"en"))} · ${esc(r.readiness.level)}</span><span>${r.mediaCount?`${r.mediaCount} media`:r.hasLink?t.link:t.noMedia}</span></button>`).join("")}</section>`).join("")}</div>`;}
